# Let's test solving for triviality across all n=1, 2, 3!
import json
from collections import defaultdict
from fractions import Fraction
import sympy as sp
import time

for n in [1, 2, 3]:
    t0 = time.time()
    with open(f'data/C_{n}_structure.json') as f:
        s1 = json.load(f)
    with open(f'data/C_{n}_evaluated.json') as f:
        e1 = json.load(f)

    basis_even = s1['basis']['even']
    basis_odd = s1['basis']['odd']
    basis = basis_odd + basis_even
    parity = s1['parity']

    bracket = defaultdict(lambda: defaultdict(dict))
    for entry in s1['structure_constants']:
        bracket[entry['X']][entry['Y']][entry['Z']] = Fraction(entry['coeff'])

    # Elementary maps
    elementary_maps = []
    for zj in basis:
        for zi in basis:
            if parity[zi] == (parity[zj] + 1) % 2:
                elementary_maps.append((zi, zj))

    # Evaluate target gamma (restricted to g, ignoring central element K)
    gamma_eval = defaultdict(Fraction)
    for t in e1['evaluated_deformation']['evaluated_gamma_constants']:
        if t['Z'] != 'K':
            gamma_eval[(t['X'], t['Y'], t['Z'])] = Fraction(t['coeff'])

    # Build system for pairs X <= Y:
    # First compute coboundary vectors for each elementary map
    elem_coboundaries = []
    for zi, zj in elementary_maps:
        res = defaultdict(Fraction)
        # Term 1: Y == zj
        for X in basis:
            px = parity[X]
            for Z, c in bracket[X][zi].items():
                res[(X, zj, Z)] += ((-1)**px) * c
        # Term 2: X == zj
        pzj = parity[zj]
        for Y in basis:
            py = parity[Y]
            for Z, c in bracket[Y][zi].items():
                res[(zj, Y, Z)] -= ((-1)**((pzj + 1)*py)) * c
        # Term 3: [X, Y]_zj != 0, Z == zi
        for X in basis:
            for Y, zdict in bracket[X].items():
                if zj in zdict:
                    res[(X, Y, zi)] -= zdict[zj]
        elem_coboundaries.append(res)

    # Collect independent equation keys (X <= Y, Z)
    eqn_keys = set()
    for idx_x, X in enumerate(basis):
        for idx_y, Y in enumerate(basis):
            if idx_x <= idx_y:
                for Z in basis:
                    if gamma_eval[(X, Y, Z)] != 0:
                        eqn_keys.add((X, Y, Z))
    for res in elem_coboundaries:
        for (X, Y, Z), v in res.items():
            if basis.index(X) <= basis.index(Y) and v != 0:
                eqn_keys.add((X, Y, Z))

    eqn_keys = sorted(list(eqn_keys))
    # Build matrix
    matrix_rows = []
    targets = []
    for k in eqn_keys:
        row = [res[k] for res in elem_coboundaries]
        matrix_rows.append(row)
        targets.append(gamma_eval[k])

    M = sp.Matrix(matrix_rows)
    b = sp.Matrix(targets)
    rank_M = M.rank()
    M_aug = M.row_join(b)
    rank_aug = M_aug.rank()

    print(f'n={n}: num_params={len(elementary_maps)}, num_eqns={len(eqn_keys)}, rank(M)={rank_M}, rank(M_aug)={rank_aug}, time={time.time()-t0:.2f}s')
    if rank_M == rank_aug:
        print(f'  --> n={n}: DEFORMATION IS A COBOUNDARY (TRIVIAL)')
    else:
        print(f'  --> n={n}: DEFORMATION IS NOT A COBOUNDARY (NON-TRIVIAL, NON-ZERO COHOMOLOGY CLASS)')
